body.script:
(function(){
 const buttons=[...document.querySelectorAll('.lang-button')];
 function setLang(lang){
   document.documentElement.lang=lang;
   localStorage.setItem('inspekt-lang',lang);
   document.querySelectorAll('[data-ru][data-uz]').forEach(el=>{el.textContent=el.dataset[lang]});
   document.querySelectorAll('[data-placeholder-ru]').forEach(el=>{el.placeholder=el.dataset['placeholder'+lang.toUpperCase().replace('RU','Ru').replace('UZ','Uz')] || el.getAttribute('data-placeholder-'+lang)});
   buttons.forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));
   document.title=lang==='uz'?'Inspekt.uz — Telegram orqali biznes nazorati':'Inspekt.uz — контроль бизнеса в Telegram';
 }
 buttons.forEach(b=>b.addEventListener('click',()=>setLang(b.dataset.lang)));
 document.querySelectorAll('a[href="#contact"]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();document.querySelector('#contact').scrollIntoView({behavior:'smooth'});}));
 const form=document.querySelector('#contact form');
 if(form) form.addEventListener('submit',e=>{e.preventDefault(); const lang=document.documentElement.lang; alert(lang==='uz'?'Rahmat! Arizangiz qabul qilindi. Tez orada siz bilan bog‘lanamiz.':'Спасибо! Заявка принята. Мы скоро свяжемся с вами.'); form.reset();});
 setLang(localStorage.getItem('inspekt-lang')||'ru');
})();
